// PREPARAR_VISION — soporta binary data00, imageBase64 y imageUrl
const item = $input.first() || {};
const prev = item.json || {};
const body = prev.body || prev || {};
const chatInput = String(body.chatInput || body.text || prev.chatInput || '');

let base64 = body.imageBase64 || body.image_base64 || prev.imageBase64 || null;
let mimeType = String(body.imageMimeType || body.image_mime_type || prev.imageMimeType || 'image/jpeg').split(';')[0];
const imageUrl = body.imageUrl || body.image_url || prev.imageUrl || null;
const hasFlag = String(body.hasImage || prev.hasImage || '') === '1' || body.hasImage === true;

const bin = (item.binary && (item.binary.data00 || item.binary.data0 || item.binary.data)) || null;
if (!base64 && bin && bin.data) {
  base64 = bin.data;
  mimeType = (bin.mimeType || mimeType).split(';')[0];
}

const hasImage = !!(base64 || imageUrl);

if (!hasImage) {
  return [{ json: prev, binary: item.binary }];
}

let apiKey = '';
try { apiKey = process.env.GOOGLE_API_KEY || process.env.GOOGLE_GEMINI_API_KEY || ''; } catch (e) {}
if (!apiKey) { try { apiKey = $vars['GOOGLE_API_KEY'] || ''; } catch (e) {} }

let imageAnalysis = '';

const _helpers = (typeof this !== 'undefined' && this.helpers) ? this.helpers : null;
async function httpReq(opts) {
  if (typeof $http !== 'undefined' && $http.request) return $http.request(opts);
  if (_helpers && _helpers.httpRequest) return _helpers.httpRequest(opts);
  throw new Error('No hay cliente HTTP disponible en el Code node');
}

try {
  if (!apiKey) {
    imageAnalysis = 'Imagen recibida en el servidor, pero falta GOOGLE_API_KEY en n8n (Railway Variables).';
  } else {
    if (!base64 && imageUrl) {
      const imgResp = await httpReq({
        method: 'GET', url: imageUrl, encoding: 'arraybuffer', returnFullResponse: true
      });
      base64 = Buffer.from(imgResp.body).toString('base64');
      mimeType = ((imgResp.headers && imgResp.headers['content-type']) || mimeType).split(';')[0];
    }
    base64 = String(base64 || '').replace(/^data:[^;]+;base64,/, '');
    if (!base64) throw new Error('No hay bytes de imagen (base64 vacio)');

    const visionResp = await httpReq({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=' + apiKey,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{
          parts: [
            {
              text: 'Sos experto en meteorologia, aviacion, navegacion y agronomia. Analiza la imagen con detalle tecnico (tipo de nubes, radar, cultivo, energia, etc). Contexto del usuario: ' + chatInput
            },
            { inlineData: { mimeType: mimeType || 'image/jpeg', data: base64 } }
          ]
        }],
        generationConfig: { temperature: 0.1, maxOutputTokens: 2000 }
      })
    });
    const parsed = typeof visionResp === 'string' ? JSON.parse(visionResp) : visionResp;
    imageAnalysis = parsed?.candidates?.[0]?.content?.parts?.[0]?.text
      || (parsed?.candidates?.[0]?.content?.parts || []).map(p => p.text).filter(Boolean).join('\n')
      || 'No se pudo extraer analisis visual.';
  }
} catch (err) {
  imageAnalysis = 'Error al procesar imagen: ' + (err.message || String(err));
}

const enrichedChat = '[ANALISIS VISUAL — VISION IA]\n' + imageAnalysis + '\n\n---\nConsulta: ' + chatInput;

return [{
  json: {
    ...prev,
    chatInput: enrichedChat,
    imageAnalysis: imageAnalysis,
    hasImage: true,
    imageMimeType: mimeType,
    body: Object.assign({}, (typeof body === 'object' && body) ? body : {}, {
      chatInput: enrichedChat,
      imageAnalysis: imageAnalysis,
      hasImage: true,
      imageMimeType: mimeType,
      imageBase64: undefined
    })
  },
  binary: item.binary || {}
}];

// 1. Obtenemos los datos del Webhook de forma segura (evita errores si el nodo cambia de nombre)
const webhookData = $('Webhook').first()?.json?.body || {};
const userMessage = webhookData.chatInput || webhookData.message || "";
const sessionId = webhookData.sessionId || webhookData.session_id || `session_${Date.now()}`;
const userId = webhookData.userId || webhookData.user_id || null;

// 🕐 2. CONFIGURACIÓN DE LÍMITES
const LIMITE_MENSAJES_MEMORIA = 10; // Cantidad máxima de intercambios
const LIMITE_CARACTERES_CONTEXTO = 4000; // Límite seguro para no saturar tokens de la IA

// 3. Obtener datos del nodo anterior (Supabase)
const inputItems = $input.all();
let datosMemoria = [];

if (inputItems && inputItems.length > 0) {
    // Filtramos para asegurarnos de que solo procesamos filas válidas de Supabase
    datosMemoria = inputItems
        .map(item => item.json)
        .filter(item => item && item.user_message && item.ai_response);
}

// Variables iniciales
let contextoTexto = "";
let esPrimeraInteraccion = true;
let intercambiosIncluidos = 0;

// 🧠 4. MOTOR DE MEMORIA (Lógica corregida)
if (datosMemoria.length > 0) {
    esPrimeraInteraccion = false;

    // PASO A: Ordenar de MÁS NUEVO a MÁS VIEJO
    // Usamos created_at o timestamp (lo que esté disponible en tu tabla)
    datosMemoria.sort((a, b) => new Date(b.created_at || b.timestamp) - new Date(a.created_at || a.timestamp));

    // PASO B: Tomar solo los últimos X mensajes
    const memoriaReciente = datosMemoria.slice(0, LIMITE_MENSAJES_MEMORIA);

    let bloquesValidos = [];
    let caracteresUsados = 0;

    // PASO C: Evaluar longitud (asegurando que siempre guardamos lo más reciente)
    for (const intercambio of memoriaReciente) {
        const bloque = `Usuario: ${intercambio.user_message}\nIA: ${intercambio.ai_response}\n\n`;

        if (caracteresUsados + bloque.length > LIMITE_CARACTERES_CONTEXTO) {
            break; // Si nos pasamos del límite, descartamos los mensajes más viejos
        }

        bloquesValidos.push(bloque);
        caracteresUsados += bloque.length;
        intercambiosIncluidos++;
    }

    // PASO D: Invertir el array para que la IA lo lea en orden cronológico natural (Viejo -> Nuevo)
    bloquesValidos.reverse();

    // PASO E: Armar el bloque de texto final
    if (bloquesValidos.length > 0) {
        contextoTexto = "### 📝 MEMORIA DE CONVERSACIÓN PREVIA ###\n";
        contextoTexto += bloquesValidos.join("");
        contextoTexto += "### FIN MEMORIA ###\n\n";
    }
}

// 📝 5. Instrucciones dinámicas para inyectar en el System Prompt
const instruccionesMemoria = esPrimeraInteraccion 
    ? "Esta es la primera interacción con este usuario en esta sesión. Responde a su solicitud directamente."
    : `Tienes contexto de los últimos ${intercambiosIncluidos} intercambios con el usuario. Úsalo para mantener la continuidad de la conversación.`;

// ️ 6. CONSTRUIR OUTPUT FINAL
const outputCompleto = {
    ...webhookData, // Pasamos de largo todo lo que venía del frontend
    session_id: sessionId,
    user_id: userId,
    mensaje_actual: userMessage,
    contexto_memoria: contextoTexto,
    es_primera_vez: esPrimeraInteraccion,
    numero_intercambios_previos: intercambiosIncluidos,
    instrucciones_memoria: instruccionesMemoria
};

// 📤 7. RETORNAR EN EL FORMATO NATIVO DE N8N
return [{ json: outputCompleto }];

// Code 2 — post-proceso seguro (nunca tumba el Respond to Webhook)
try {
const aiNodeData = $input.first()?.json || {};

function tcFindMostrarGrafico(obj, depth, seen) {
  if (depth > 6 || obj == null) return null;
  if (typeof obj === 'object') {
    if (!seen) seen = new Set();
    if (seen.has(obj)) return null;
    seen.add(obj);
  }
  if (typeof obj === 'string') {
    const m = obj.match(/\[MOSTRAR_GRAFICO\][\s\S]*/i);
    return m ? m[0] : null;
  }
  if (Array.isArray(obj)) {
    for (const item of obj) {
      const f = tcFindMostrarGrafico(item, depth + 1, seen);
      if (f) return f;
    }
    return null;
  }
  if (typeof obj === 'object') {
    for (const k of Object.keys(obj)) {
      try {
        const f = tcFindMostrarGrafico(obj[k], depth + 1, seen);
        if (f) return f;
      } catch (e) {}
    }
  }
  return null;
}

let respuestaIA = aiNodeData.output || aiNodeData.text || aiNodeData.response || "";
if (!String(respuestaIA).includes("[MOSTRAR_GRAFICO]")) {
  const bloque = tcFindMostrarGrafico(aiNodeData, 0);
  if (bloque) respuestaIA = String(respuestaIA).trim() + "\n\n" + bloque;
}
aiNodeData.output = respuestaIA;

let chart_block = '';
const _cm = String(respuestaIA).match(/\[MOSTRAR_GRAFICO\][\s\S]*/i);
if (_cm) chart_block = _cm[0];
else {
  const _cb = tcFindMostrarGrafico(aiNodeData, 0);
  if (_cb) {
    chart_block = _cb;
    if (!String(respuestaIA).includes('[MOSTRAR_GRAFICO]')) {
      respuestaIA = String(respuestaIA).trim() + '\n\n' + _cb;
    }
  }
}

try {
  const steps = aiNodeData.intermediateSteps || aiNodeData.intermediate_steps || [];
  if (!chart_block && Array.isArray(steps)) {
    for (const step of steps) {
      const obs = (step && (step.observation != null ? step.observation : step)) || null;
      const found = tcFindMostrarGrafico(obs, 0);
      if (found) {
        chart_block = found;
        if (!String(respuestaIA).includes('[MOSTRAR_GRAFICO]')) {
          respuestaIA = String(respuestaIA).trim() + '\n\n' + found;
        }
        break;
      }
    }
  }
} catch (e) {}

const webhookData = $('Webhook').first()?.json?.body || {};
const sessionId = webhookData.sessionId || webhookData.session_id || `session_${Date.now()}`;
const userId = webhookData.userId || webhookData.user_id || null;
const userMessage = webhookData.chatInput || webhookData.message || "";

const respuestaLower = String(respuestaIA).toLowerCase();
const sectoresPalabras = {
    'naval': ['naval', 'mar', 'puerto', 'navegación', 'barco', 'marítimo', 'olas', 'marea', 'nudos', 'douglas'],
    'agro': ['agrícola', 'cultivo', 'siembra', 'cosecha', 'campo', 'rural', 'agricultura', 'riego', 'suelo'],
    'aereo': ['aéreo', 'vuelo', 'aviación', 'aeropuerto', 'avión', 'cielo', 'metar', 'qnh'],
    'energia': ['energía', 'eléctrico', 'solar', 'eólico', 'renovable', 'panel', 'turbina', 'radiación']
};
let sectorDetectado = null;
for (const [sector, palabras] of Object.entries(sectoresPalabras)) {
    if (palabras.some(palabra => respuestaLower.includes(palabra))) {
        sectorDetectado = sector;
        break;
    }
}

const datosMeteorologicos = {
    temperatura: respuestaLower.includes('temperatura') || respuestaLower.includes('°c'),
    viento: respuestaLower.includes('viento') || respuestaLower.includes('km/h') || respuestaLower.includes('nudos') || respuestaLower.includes('kt'),
    humedad: respuestaLower.includes('humedad') || respuestaLower.includes('%'),
    precipitacion: respuestaLower.includes('lluvia') || respuestaLower.includes('precipitación') || respuestaLower.includes('mm')
};
const respuestaContieneClima = Object.values(datosMeteorologicos).some(Boolean);

const urlRegex = /(https:\/\/app\.powerbi\.com[^\s\)]+)/;
const matchPowerBI = String(respuestaIA).match(urlRegex);
const powerbi_url = matchPowerBI ? matchPowerBI[0] : null;

let texto_limpio = String(respuestaIA);
if (powerbi_url) {
    texto_limpio = texto_limpio.replace(/\[.*?\]\(https:\/\/app\.powerbi\.com.*?\)/g, "");
    texto_limpio = texto_limpio.replace(powerbi_url, "");
}
texto_limpio = texto_limpio.trim();

const contextoPrevioObj = {
    sector_conversacion: sectorDetectado,
    contiene_datos_clima: respuestaContieneClima,
    timestamp_inicio: new Date().toISOString()
};
const metadatosObj = {
    user_agent: webhookData.headers?.['user-agent'] || null,
    ai_agent_used: true,
    datos_meteorologicos_detectados: datosMeteorologicos
};

const outputCompleto = {
    session_id: sessionId,
    user_id: userId,
    user_message: userMessage,
    ai_response: respuestaIA,
    sector: sectorDetectado,
    ubicacion: webhookData.ubicacion || null,
    contexto_previo: contextoPrevioObj,
    metadatos: metadatosObj,
    output: respuestaIA,
    texto_limpio: texto_limpio,
    chart_block: (typeof chart_block !== 'undefined' ? chart_block : ''),
    powerbi_url: powerbi_url,
    es_respuesta_climatica: respuestaContieneClima
};

return [{ json: outputCompleto }];

} catch (err) {
  const fallback = ($input.first()?.json?.output || $input.first()?.json?.text || 'Error procesando la respuesta de la IA. Reintentá.');
  return [{
    json: {
      output: String(fallback),
      texto_limpio: String(fallback),
      chart_block: '',
      powerbi_url: null,
      session_id: 'error',
      user_id: null,
      user_message: '',
      ai_response: String(fallback),
      sector: null,
      es_respuesta_climatica: false,
      _code2_error: String(err && err.message ? err.message : err)
    }
  }];
}

