// Validacion de origen — secreto compartido Django ↔ n8n
// NO uses el tab Variables de n8n (pide plan de pago).
// Configurá N8N_WEBHOOK_SECRET en Railway → servicio n8n → Variables
// y el mismo valor en Django .env / Render. También: N8N_BLOCK_ENV_ACCESS_IN_NODE=false
let secretEsperado = '';
try { secretEsperado = String(process.env.N8N_WEBHOOK_SECRET || '').trim(); } catch (e) {}
if (!secretEsperado) {
  try { secretEsperado = String($vars['N8N_WEBHOOK_SECRET'] || '').trim(); } catch (e) {}
}

const headers = $input.first().json.headers || {};
const secretRecibido = String(
  headers['x-n8n-secret'] || headers['X-N8N-Secret'] || ''
).trim();

if (secretEsperado && secretRecibido !== secretEsperado) {
  return [{
    json: {
      output: 'Error de autenticación con n8n: N8N_WEBHOOK_SECRET inválido o ausente en Django. Configurá el mismo valor en Railway (Variables del servicio n8n) y en tu .env / Render.',
      texto_limpio: 'Error de autenticación con el servidor de IA (secreto).',
      error: 'n8n_secret_mismatch'
    }
  }];
}

return $input.all();
